using System;using System.IO;using System.Collections.Generic;using MapSharedProps;using MapSharedProps.EditorTools;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class PineWindChecks {
 [Serializable]class Probe{public float time,strength,rot,sx,sy;public float[] values;}
 [Serializable]class Fixture{public Probe[] cases;}
 [Serializable]class Check{public string name,status,detail;}
 [Serializable]class Report{public string status,unityVersion;public Check[] checks;public Probe[] probes;}
 static readonly List<Check> checks=new List<Check>();static void Verify(string n,bool ok,string d=""){checks.Add(new Check{name=n,status=ok?"Passed":"Failed",detail=d});if(!ok)throw new Exception(n+": "+d);}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,k);return i>=0?a[i+1]:null;}
 public static void Run(){string output=Arg("-wind-output");int code=0;var results=new List<Probe>();
  try{
   EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var lib=MapSharedPropsBuilder.ReadLibrary(Path.Combine(output,"shared_props.json"));var built=MapSharedPropsBuilder.Build(Path.Combine(output,"export"));var driver=built.root.GetComponent<SharedPineWind>();
   Verify("Optional wind contract imports and weather-none stays off",driver!=null&&!driver.windEnabled&&driver.editorZero==new Vector2(12,12));
   foreach(var id in new[]{"rock","fern","log","stump","rootfan"})Verify(id+" material remains fixed",built.prefabs[id].GetComponent<Renderer>().sharedMaterial.GetVector("_PineBand").w==0);
   MapSharedPropsBuilder.ConfigureWind(driver,Path.Combine(output,"storm-meta.json"));Verify("Exported storm amount and canonical direction match",driver.windEnabled&&Mathf.Abs(driver.strength-.55f)<1e-6f&&Mathf.Abs(driver.direction.x-.9285f)<1e-6f&&Mathf.Abs(driver.direction.y+.3714f)<1e-6f);
   driver.editorZero=Vector2.zero;driver.direction=new Vector2(.8f,.6f);driver.useClock=false;
   var a=Array.Find(lib.assets,x=>x.id=="pine");var mesh=built.prefabs["pine"].GetComponent<MeshFilter>().sharedMesh;Verify("Pine retains 134 triangles",mesh.triangles.Length==402);
   var fixture=JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.Combine(output,"browser-wind.json")));var src=new Texture2D(mesh.vertexCount,1,TextureFormat.RGBAFloat,false,true);src.filterMode=FilterMode.Point;src.wrapMode=TextureWrapMode.Clamp;var colors=new Color[mesh.vertexCount];for(int i=0;i<colors.Length;i++)colors[i]=new Color(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2],a.uv[i*2+1]);src.SetPixels(colors);src.Apply();var probe=new Material(Shader.Find("Hidden/MapSharedProps/PineWindProbe"));probe.SetVector("_PineBand",new Vector4(2.15f,6.408f,.12f,1));probe.SetVector("_PineWaves",new Vector4(1.7f,.65f,2.9f,.35f));probe.SetVector("_PinePhase",new Vector4(.17f,.13f,0,0));
   foreach(var c in fixture.cases){driver.windEnabled=c.strength>0;driver.strength=c.strength;driver.Apply(c.time);probe.SetMatrix("_ProbeMatrix",Matrix4x4.TRS(new Vector3(2,0,3),Quaternion.Euler(0,-c.rot*Mathf.Rad2Deg,0),new Vector3(c.sx,c.sy,c.sx)));var rt=new RenderTexture(mesh.vertexCount,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(src,rt,probe);var prev=RenderTexture.active;RenderTexture.active=rt;var read=new Texture2D(mesh.vertexCount,1,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,mesh.vertexCount,1),0,0);read.Apply();var pixels=read.GetPixels();float error=0;var values=new float[pixels.Length*4];for(int i=0;i<pixels.Length;i++){values[i*4]=pixels[i].r;values[i*4+1]=pixels[i].g;values[i*4+2]=pixels[i].b;values[i*4+3]=pixels[i].a;for(int k=0;k<4;k++)error=Mathf.Max(error,Mathf.Abs(values[i*4+k]-c.values[i*4+k]));}Verify("Browser/Unity GPU probe t="+c.time,error<.00002f,"max metres="+error);results.Add(new Probe{time=c.time,strength=c.strength,rot=c.rot,sx=c.sx,sy=c.sy,values=values});RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);}
   var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
   var tree=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs["pine"]);var realMat=tree.GetComponent<Renderer>().sharedMaterial;var mat=new Material(Shader.Find("Hidden/MapSharedProps/PineWindReference"));mat.SetTexture("_BaseMap",realMat.GetTexture("_BaseMap"));tree.GetComponent<Renderer>().sharedMaterial=mat;
   var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.05f,0);floor.transform.localScale=new Vector3(20,.1f,20);var fm=new Material(Shader.Find("Universal Render Pipeline/Unlit"));fm.SetColor("_BaseColor",new Color(.5333f,.5961f,.451f));floor.GetComponent<Renderer>().sharedMaterial=fm;
   var human=GameObject.CreatePrimitive(PrimitiveType.Capsule);human.transform.position=new Vector3(.9f,.9f,0);human.transform.localScale=new Vector3(.6f,.9f,.6f);var hm=new Material(Shader.Find("Universal Render Pipeline/Unlit"));hm.SetColor("_BaseColor",new Color(224/255f,173/255f,118/255f));human.GetComponent<Renderer>().sharedMaterial=hm;
   var camera=new GameObject("Wind comparison camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.orthographic=true;camera.orthographicSize=3.5f;camera.aspect=1.6f;camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(184/255f,196/255f,204/255f);camera.transform.position=new Vector3(0,3.2f,-12);camera.transform.LookAt(new Vector3(0,3.2f,0));
   Capture(camera,output,"unity-warmup.png");foreach(string name in new[]{"static","off","phase-0","phase-1","phase-2","phase-3"}){float t=name=="off"?3:name=="phase-1"?.5f:name=="phase-2"?1.5f:name=="phase-3"?4:0;driver.windEnabled=name!="off"&&name!="static";driver.strength=1;driver.Apply(t);mat.SetVector("_PineBand",new Vector4(2.15f,6.408f,.12f,name=="static"?0:1));Capture(camera,output,"unity-"+name+".png");}
   tree.GetComponent<Renderer>().sharedMaterial=realMat;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white*.3f;var sun=new GameObject("Shadow sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(3,-7,5));RenderSettings.sun=sun;var litGround=new Material(Shader.Find("Universal Render Pipeline/Lit"));litGround.SetColor("_BaseColor",new Color(.65f,.7f,.6f));floor.GetComponent<Renderer>().sharedMaterial=litGround;camera.orthographicSize=4.5f;camera.transform.position=new Vector3(7,8,-10);camera.transform.LookAt(new Vector3(0,2.6f,0));
   foreach(float t in new[]{0f,1.5f}){driver.windEnabled=true;driver.strength=1;driver.Apply(t);Capture(camera,output,"unity-shadow-"+t.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+".png");}
   var errors=new List<string>();foreach(var m in ShaderUtil.GetShaderMessages(Shader.Find("MapSharedProps/Lit")))if(m.severity.ToString()=="Error")errors.Add(m.message);Verify("Forward and shadow shader compile",errors.Count==0,string.Join(";",errors));Verify("Wind uses a shadow caster pass",realMat.FindPass("ShadowCaster")>=0);
   GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;driver.windEnabled=false;driver.Apply(0);
  }catch(Exception e){code=1;checks.Add(new Check{name="Unexpected failure",status="Failed",detail=e.ToString()});Debug.LogException(e);}
  File.WriteAllText(Path.Combine(output,"unity-wind.json"),JsonUtility.ToJson(new Report{status=code==0?"Passed":"Failed",unityVersion=Application.unityVersion,checks=checks.ToArray(),probes=results.ToArray()},true));EditorApplication.Exit(code);
 }
 static void Capture(Camera camera,string output,string name){var rt=new RenderTexture(1024,640,24,RenderTextureFormat.ARGB32);rt.Create();camera.targetTexture=rt;camera.allowMSAA=false;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});var prev=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1024,640,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1024,640),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name),image.EncodeToPNG());RenderTexture.active=prev;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
}
